reviewer.reply:
{
    "verdict": "reject",
    "blockers": [
        {
            "claim": "Dropped frame notification mechanism was completely removed, breaking error reporting - the notifyDropped() method and its callers were deleted, so dropped frames are never reported to the UI",
            "file": "app/qttunebridge.cpp",
            "quote": "// FIX: report drops from the worker path too. Previously drops were\n// only surfaced from handleFrameInternal, which never runs while the\n// backlog is saturated — exactly when the user needs to know."
        },
        {
            "claim": "Signal decoding now uses hardcoded 8-byte buffer instead of actual payload length, breaking CAN-FD support for frames >8 bytes",
            "file": "app/qttunebridge.cpp",
            "quote": "if (qttune_decode_signal(&def, frame->data, 8, &val) == 0)"
        },
        {
            "claim": "Staging buffer is cleared on each frame instead of being merged across frames, defeating the coalescing purpose",
            "file": "app/qttunebridge.cpp",
            "quote": "m_stagingBuffer.clear();"
        },
        {
            "claim": "setSignalSet takes opaque void* but the comment in the header says 'opaque pointer to QttuneSignalSet' - this violates C ABI integrity by exposing the concrete type in comments while claiming it's opaque",
            "file": "app/qttunebridge.h",
            "quote": "void setSignalSet(const void* set);  // opaque pointer to QttuneSignalSet"
        }
    ],
    "questions": [
        "What is the intended source of drop notifications now that notifyDropped() was removed?",
        "Why was the coalescing merge behavior removed from the staging buffer logic?",
        "Where should the dropped frame count be reported if not via notifyDropped()?"
    ],
    "nits": [
        "Removed #include <algorithm> is fine since it's no longer needed",
        "Removed m_dropNotifyPending atomic is fine since the coalescing logic was removed"
    ]
